UPDATE payment_approval_document
SET submission_status = #{submissionStatus}
WHERE document_id = (
    SELECT document_id
    FROM payment_approval_document
    WHERE report_no = #{accidentNumber}
    ORDER BY created_at DESC
    LIMIT 1
)
AND submission_status = #{currentStatus}

UPDATE accident_report
SET accident_status = 'APPROVAL_REQUIRED'
WHERE report_no = #{accidentNumber}

UPDATE accident_report
SET accident_status = #{accidentStatus}
WHERE report_no = #{accidentNumber}
